#[test]
fn commdemo_language_instantiates() {
    let lang = CommDemoLanguage;
    assert_eq!(lang.name(), "CommDemo");
}

#[test]
fn commdemo_metadata_populated() {
    let lang = CommDemoLanguage;
    let meta = lang.metadata();
    assert!(!meta.types().is_empty(), "language should have at least one type");
    assert!(!meta.terms().is_empty(), "language should have at least one term");
}

#[test]
fn unit_commdemo_proc_pzero() {
    let term = Proc::PZero;
    let displayed = format!("{}", term);
    assert!(!displayed.is_empty(), "Display should produce non-empty output for PZero");
    if let Ok(parsed) = Proc::parse(&displayed) {
        let re_displayed = format!("{}", parsed);
        assert_eq!(
            displayed, re_displayed,
            "Roundtrip failed for PZero: {} != {}",
            displayed, re_displayed
        );
    }
}

