#[test]
fn unit_commdemo_proc_poutput() {
    mettail_runtime::clear_var_cache();
    let term = Proc::POutput(std::sync::Arc::new(Name::Na), std::sync::Arc::new(Name::Na));
    let displayed = format!("{}", term);
    assert!(!displayed.is_empty(), "Display should produce non-empty output for POutput");
    if let Ok(parsed) = Proc::parse(&displayed) {
        let re_displayed = format!("{}", parsed);
        assert_eq!(
            displayed, re_displayed,
            "Roundtrip failed for POutput: {} != {}",
            displayed, re_displayed
        );
    }
}

#[test]
fn unit_commdemo_proc_pfor() {
    mettail_runtime::clear_var_cache();
    let term = Proc::PFor(
        std::sync::Arc::new(Name::Na),
        mettail_runtime::Scope::new(
            mettail_runtime::Binder(mettail_runtime::get_or_create_var("a")),
            std::sync::Arc::new(Proc::PZero),
        ),
    );
    let displayed = format!("{}", term);
    assert!(!displayed.is_empty(), "Display should produce non-empty output for PFor");
}

